    private static function upload(string $alt):?array{if(empty($_FILES['image_file']['tmp_name']))return null;$f=$_FILES['image_file'];if((int)$f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Image upload failed.');if((int)$f['size']>10485760)throw new RuntimeException('Choose an image up to 10 MB.');$check=wp_check_filetype_and_ext($f['tmp_name'],$f['name']);if(!in_array($check['type']??'', ['image/jpeg','image/png','image/webp'],true))throw new RuntimeException('Choose a JPEG, PNG, or WebP image.');if(trim($alt)==='')$alt='Community image';require_once ABSPATH.'wp-admin/includes/file.php';$r=wp_handle_upload($f,['test_form'=>false,'mimes'=>['jpg'=>'image/jpeg','jpeg'=>'image/jpeg','png'=>'image/png','webp'=>'image/webp']]);if(isset($r['error']))throw new RuntimeException('Image upload failed.');$relative=str_replace(wp_upload_dir()['basedir'].'/','',$r['file']);$ref='wp-content/uploads/'.$relative;$a=['attachment_id'=>'upload:'.substr(hash('sha256',$relative),0,16),'attachment_type'=>'image','source_kind'=>'local_upload','source_reference'=>$ref,'title'=>sanitize_file_name($f['name']),'description'=>'Locally staged Community image.','alt_text'=>$alt,'mime_type'=>$r['type'],'file_size'=>(int)$f['size'],'rights_status'=>'author_declared','moderation_state'=>'clear','lifecycle_state'=>'active','created_at'=>gmdate('Y-m-d H:i:s')];self::$created[]=$r['file'];return $a;}
    private static function cleanup():void{foreach(self::$created as $p)if(is_string($p)&&is_file($p))@unlink($p);self::$created=[];}
    private static function submit():void{if(!isset($_POST['tnet_topic_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tnet_topic_nonce'])),'tnet_community_topic'))self::form(['Nonce verification failed.']);$community=sanitize_text_field(wp_unslash($_POST['community_id']??''));$sid=sanitize_text_field(wp_unslash($_POST['submission_id']??''))?:'web-'.wp_generate_uuid4();$title=sanitize_text_field(wp_unslash($_POST['title']??''));$body=sanitize_textarea_field(wp_unslash($_POST['body']??''));$mode=sanitize_key(wp_unslash($_POST['post_mode']??'discussion'));$urls=self::urls($body);$selected=esc_url_raw(wp_unslash($_POST['representative_url']??''));$representative=in_array($selected,$urls,true)?$selected:($urls[0]??'');$choice=sanitize_key(wp_unslash($_POST['preview_choice']??'keep'));$alt=sanitize_text_field(wp_unslash($_POST['attachment_alt']??''));$errors=[];if(!isset(self::COMMUNITIES[$community]))$errors[]='Choose a valid Community.';if($title==='')$errors[]='Enter a topic title.';if($body==='')$errors[]='Enter the topic body.';if(!isset(self::MODES[$mode]))$mode='discussion';$attachment=null;try{$attachment=self::upload($alt); }catch(Throwable $e){$errors[]=$e->getMessage();}if($errors){self::cleanup();self::form($errors,compact('community','sid','title','body','mode','representative','choice','alt'));}try{$preview=(new TNet_Community_Link_Attachment_Service())->prepare($representative,$choice);$draft=['submission_id'=>$sid,'community_id'=>$community,'author_id'=>'user:'.(int)get_current_user_id(),'post_type'=>'topic','title'=>$title,'body'=>$body,'parent_post_id'=>null,'visibility'=>'public','publication_mode'=>'post_first','moderation_input'=>'clear','compatibility_refs'=>['composer'=>['post_mode'=>$mode,'attachments'=>$attachment?[$attachment]:[],'links'=>array_map(static fn($u)=>['url'=>$u,'enrichment'=>'mocked'],$urls),'preview'=>$preview,'representative_url'=>$representative]],'audit_context'=>['source'=>'local-natural-composer']];$result=(n