        $html.='(function(){const b=document.getElementById("body"),s=document.getElementById("representative_url"),f=document.getElementById("image_file"),d=document.getElementById("dropzone"),st=document.getElementById("image-status"),pr=document.getElementById("image-preview"),rm=document.getElementById("remove-image"),alt=document.getElementById("attachment_alt"),lp=document.getElementById("link-preview"),pc=document.getElementById("preview_choice");let objectUrl=null;const urls=()=>[...new Set((b.value.match(/https:\/\/[^\\s<>"\']+/gi)||[]).map(u=>u.replace(/[.,!?;:)]+$/,"")))];function links(){const old=s.value;const us=urls();s.innerHTML="<option value=\"\">No link preview</option>";us.forEach(u=>{const o=document.createElement("option");o.value=u;o.textContent=u;s.appendChild(o)});s.value=us.includes(old)?old:(us[0]||"");preview()}function preview(){const u=s.value;lp.hidden=!u||pc.value!=="keep";lp.textContent=lp.hidden?"":"Mocked preview: "+u}function clear(){if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=null;f.value="";pr.innerHTML="";alt.required=false;st.textContent="Empty: paste, drop, or select one image."}function stage(file){if(!file)return;if(!["image/jpeg","image/png","image/webp"].includes(file.type)||file.size>10485760){clear();st.textContent="Error: choose a JPEG, PNG, or WebP image up to 10 MB.";return}if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);try{const dt=new DataTransfer();dt.items.add(file);f.files=dt.files}catch(e){st.textContent="Error: reselect the image with Choose a photo.";return}st.textContent="Staged: "+file.name+" (ready to submit)";pr.innerHTML="<img src=\""+objectUrl+"\" alt=\"\" style=\"max-width:100%;max-height:240px\"><p>"+file.name+"</p>";alt.required=true}b.addEventListener("input",links);s.addEventListener("change",preview);pc.addEventListener("change",preview);f.addEventListener("change",e=>stage(e.target.files[0]));rm.addEventListener("click",clear);["dragenter","dragover"].fo