        $html=str_replace('<div id="dropzone" class="dropzone">Drop one JPEG, PNG, or WebP image here<br><button type="button" class="secondary" id="add-photo" aria-label="Add photo">📷 Add Photo</button><input id="image_file" name="image_file" type="file" accept="image/jpeg,image/png,image/webp" hidden></div><div id="image-preview"></div>','<div id="image-preview"></div><div id="dropzone" class="dropzone"><span class="drop-hint">Drop one JPEG, PNG, or WebP image here<br></span><button type="button" class="secondary" id="add-photo" aria-label="Add photo">📷 Add Photo</button><input id="image_file" name="image_file" type="file" accept="image/jpeg,image/png,image/webp" hidden></div>',$html);
        $html=str_replace('f=document.getElementById("image_file"),add=document.getElementById("add-photo"),d=document.getElementById("dropzone")','f=document.getElementById("image_file"),add=document.getElementById("add-photo"),staged=document.getElementById("staged-content"),d=document.getElementById("dropzone")',$html);
        $html=str_replace('function clear(){if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=null;f.value="";pr.innerHTML="";alt.required=false;st.textContent="Empty: paste, drop, or select one image."}','function clear(){if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=null;f.value="";pr.innerHTML="";alt.required=false;staged.classList.remove("has-image");d.classList.remove("has-image");st.textContent="Empty: paste, drop, or select one image."}',$html);
